          "en": "Delayed? If we had booked an earlier flight, we wouldn't be worrying about this now. This is frustrating.",
          "pt": "Atrasado? Se tivéssemos reservado um voo mais cedo, não estaríamos preocupados com isso agora. Isso é frustrante."
