    "grammar": [
      {
        "title": {
          "en": "Advanced Passive Structures: Modals and Reporting Verbs",
          "pt": "Estruturas Passivas Avançadas: Modais e Verbos de Relato"
        },
        "examples": [
          {
            "en": "The new policy must be implemented by next quarter.",
            "pt": "A nova política deve ser implementada até o próximo trimestre."
          },
          {
            "en": "It is believed that the market will recover soon.",
            "pt": "Acredita-se que o mercado se recuperará em breve."
          },
          {
            "en": "The CEO is said to be negotiating a major deal.",
            "pt": "Diz-se que o CEO está negociando um grande acordo."
          }
        ],
        "rule": {
          "en": "Advanced passive structures allow for more nuanced and formal communication, especially in business contexts. The passive with modals follows the structure: modal verb + be + past participle (e.g., must be done, should be considered, can be improved). The passive with reporting verbs (e.g., say, believe, report, know, think, expect, understand) typically takes two forms: 'It is said/believed/known that...' or 'Subject + is/are said/believed/known to + infinitive'. These structures are used when the agent is unknown, unimportant, or to give a statement more authority/objectivity without naming a source.",
          "pt": "Estruturas passivas avançadas permitem uma comunicação mais matizada e formal, especialmente em contextos de negócios. A voz passiva com modais segue a estrutura: verbo modal + be + particípio passado (ex: deve ser feito, deveria ser considerado, pode ser melhorado). A voz passiva com verbos de relato (ex: dizer, acreditar, relatar, saber, pensar, esperar, entender) geralmente assume duas formas: 'It is said/believed/known that...' ou 'Sujeito + is/are said/believed/known to + infinitivo'. Essas estruturas são usadas quando o agente é desconhecido, sem importância, ou para dar a uma afirmação mais autoridade/objetividade sem nomear uma fonte."
        },
        "mistakes": [
          {
            "en": "Incorrect: The report is believed being published next week. (Incorrect tense/form of 'be')",
            "pt": "Incorreto: O relatório é acreditado sendo publicado na próxima semana. (Tempo/forma incorreta de 'be')"
          },
          {
            "en": "Incorrect: They must improving the customer service. (Active voice where passive is intended, missing 'be')",
            "pt": "Incorreto: Eles devem melhorando o serviço ao cliente. (Voz ativa onde a passiva é pretendida, faltando 'be')"
          }
        ]
      }
    ],
