          "pt": "Trabalhe em dupla. Escolha duas questões globais diferentes da lista de vocabulário (por exemplo, desigualdade e migração). Discuta como essas questões estão interconectadas e proponha duas abordagens ou políticas distintas para abordá-las. Use os phrasal verbs avançados e as expressões formais de resumo para apresentar suas ideias."
