          "pt": "Em grupos de três, simule um cenário de negociação. Um aluno é representante de uma nação em desenvolvimento, outro de uma nação desenvolvida e o terceiro é um mediador da ONU. O objetivo é chegar a um acordo sobre uma política de reforma para uma questão global escolhida. Vocês devem usar o vocabulário, os phrasal verbs avançados e as expressões formais de resumo para argumentar seus pontos e chegar a um consenso. O mediador deve resumir formalmente o resultado."
