        "pt": "Nesta unidade, exploramos o vocabulário chave de questões globais e aprendemos phrasal verbs avançados como 'get around to', 'look into' e 'come across' para expressar significados matizados. Também dominamos expressões formais de resumo para transmitir eficazmente informações complexas em contextos profissionais."
