    "grammar": [
      {
        "title": {
          "en": "Idiomatic expressions for describing challenges and effort",
          "pt": "Expressões idiomáticas para descrever desafios e esforço"
        },
        "examples": [
          {
            "en": "Completing the marathon was an uphill battle for John, but he finished.",
            "pt": "Completar a maratona foi uma batalha difícil para John, mas ele terminou."
          },
          {
            "en": "The team went the extra mile to ensure the client was satisfied.",
            "pt": "A equipe foi além para garantir que o cliente estivesse satisfeito."
          },
          {
            "en": "Despite hitting a brick wall with the research, they found a solution.",
            "pt": "Apesar de ter batido de frente com a pesquisa, eles encontraram uma solução."
          }
        ],
        "rule": {
          "en": "Idiomatic expressions related to challenges and effort are common in English. They are phrases whose meaning cannot be deduced from the individual words. They provide vivid and concise ways to describe difficulties, hard work, or going beyond expectations. Examples include 'an uphill battle' (a very difficult struggle), 'to go the extra mile' (to make a special effort), 'to hit a brick wall' (to face an insurmountable obstacle), 'to jump through hoops' (to go through an elaborate or difficult process), and 'to bite the bullet' (to endure a difficult situation).",
          "pt": "Expressões idiomáticas relacionadas a desafios e esforço são comuns em inglês. São frases cujo significado não pode ser deduzido das palavras individuais. Elas fornecem maneiras vívidas e concisas de descrever dificuldades, trabalho árduo ou ir além das expectativas. Exemplos incluem 'an uphill battle' (uma luta muito difícil), 'to go the extra mile' (fazer um esforço especial), 'to hit a brick wall' (enfrentar um obstáculo intransponível), 'to jump through hoops' (passar por um processo elaborado ou difícil) e 'to bite the bullet' (suportar uma situação difícil)."
        },
        "mistakes": [
          {
            "en": "Incorrect: 'It was a hill battle.' (Missing 'uphill' to form the idiom)",
            "pt": "Incorreto: 'Foi uma batalha de colina.' (Faltando 'uphill' para formar o idioma)"
          },
          {
            "en": "Incorrect: 'They took the extra mile.' (Incorrect verb, should be 'went')",
            "pt": "Incorreto: 'Eles pegaram a milha extra.' (Verbo incorreto, deveria ser 'foram')"
          }
        ]
      }
    ],
