        "en": "In this unit, we explored psychology mindset vocabulary, including terms like motivation, resilience, and growth mindset. We also learned idiomatic expressions for describing challenges and effort, such as 'an uphill battle' and 'go the extra mile', alongside key leadership teamwork phrases. These tools are vital for effective communication in professional and collaborative contexts.",
