    "grammar": [
      {
        "title": {
          "en": "Cleft Sentences (It/What) for Emphasis and Focus",
          "pt": "Orações Clivadas (It/What) para Ênfase e Foco"
        },
        "examples": [
          {
            "en": "What really matters is consistency.",
            "pt": "O que realmente importa é a consistência."
          },
          {
            "en": "It was the feedback that changed my approach.",
            "pt": "Foi o feedback que mudou minha abordagem."
          },
          {
            "en": "What we need is a more efficient system.",
            "pt": "O que precisamos é um sistema mais eficiente."
          }
        ],
        "rule": {
          "en": "Cleft sentences are used to emphasize a particular part of a sentence. 'It-clefts' (It + be + emphasized element + that/who/which clause) emphasize a subject, object, or adverbial. 'What-clefts' (What + subject + verb + be + emphasized element) emphasize the action or object of a verb.",
          "pt": "Orações clivadas são usadas para enfatizar uma parte específica de uma frase. 'It-clefts' (It + verbo 'to be' + elemento enfatizado + cláusula that/who/which) enfatizam um sujeito, objeto ou advérbio. 'What-clefts' (What + sujeito + verbo + verbo 'to be' + elemento enfatizado) enfatizam a ação ou o objeto de um verbo."
        },
        "mistakes": [
          {
            "en": "Incorrect: What is important is to finish the project fast. (Emphasizing the action with 'what' can be clumsy if 'to finish' is not the focus.)",
            "pt": "Incorreto: What is important is to finish the project fast. (Enfatizar a ação com 'what' pode ser desajeitado se 'to finish' não for o foco principal.)"
          },
          {
            "en": "Incorrect: It was the new app which I installed. (Using 'which' for a person when 'who' or 'that' is more natural.)",
            "pt": "Incorreto: It was the new app which I installed. (Usar 'which' para uma pessoa quando 'who' ou 'that' é mais natural.)"
          }
        ]
      }
    ],
